window.EBOOK_OPENING_EXPANDED = {
  id: "pembuka",
  label: "Pembuka",
  title: "Pengantar",
  summary: "Ubah cara pandang: WhatsApp bukan tempat berburu nomor, melainkan kanal untuk melanjutkan hubungan dengan orang yang sudah memberi izin dan menunjukkan minat.",
  blocks: [
    { type: "subhead", text: "Kenapa buku ini ditulis" },
    { type: "paragraph", text: "Banyak pemilik bisnis memulai WhatsApp marketing dari pertanyaan yang keliru: di mana mendapatkan ribuan nomor untuk dikirimi penawaran? Pertanyaan itu menganggap nomor telepon sebagai leads. Padahal nomor hanyalah data kontak. Lead adalah orang yang memahami konteks hubungan, menunjukkan minat pada topik atau solusi tertentu, dan memberi jalan bagi bisnis untuk melakukan tindak lanjut. Perbedaan ini menentukan apakah sebuah pesan terasa membantu atau justru menjadi gangguan." },
    { type: "paragraph", text: "Buku ini ditulis untuk memindahkan fokus dari mengumpulkan nomor menuju membangun sistem. Sistem tersebut menarik orang yang tepat, menawarkan sesuatu yang berguna, menangkap izin dan konteks, menyimpan data secara rapi, lalu menindaklanjuti secara relevan. WhatsApp memiliki peran penting, tetapi posisinya berada setelah lead terbentuk. Ia adalah kanal percakapan dan follow-up, bukan mesin ajaib yang mengubah daftar acak menjadi calon pembeli." },
    { type: "subhead", text: "Kesalahan memahami WhatsApp Marketing" },
    { type: "paragraph", text: "WhatsApp sering disamakan dengan tombol broadcast: masukkan sebanyak mungkin kontak, kirim promosi, lalu berharap sebagian membeli. Masalahnya bukan hanya pada jumlah pesan. Penerima tidak tahu siapa pengirimnya, mengapa mereka dihubungi, dan apa hubungan penawaran tersebut dengan kebutuhan mereka. Tanpa konteks, pesan yang sebenarnya bagus pun kehilangan makna. Marketing berubah dari upaya menciptakan nilai menjadi interupsi." },
    { type: "paragraph", text: "Pendekatan yang lebih sehat dimulai sebelum chat pertama. Misalnya, pemilik jasa desain membuat checklist singkat untuk membantu calon klien menilai kesiapan rebranding. Pengunjung membaca konten, meminta checklist, memilih menerima tindak lanjut, dan menjawab pertanyaan mengenai jenis bisnisnya. Ketika pesan WhatsApp datang, penerima mengenali alasan kontak tersebut. Bisnis pun mempunyai data minat, sumber lead, dan masalah yang sedang dihadapi—bukan sekadar sebuah nomor." },
    { type: "subhead", text: "Dari database nomor menuju database calon customer" },
    { type: "paragraph", text: "Database calon customer seharusnya menjawab beberapa pertanyaan sederhana: orang ini datang dari mana, tertarik pada apa, sudah menerima apa, pernah melakukan tindakan apa, dan tindak lanjut mana yang relevan berikutnya. Informasi ini tidak harus rumit. Untuk kedai kopi yang menjual paket langganan kantor, satu lead dapat dicatat sebagai: datang dari QR code di acara komunitas, mengunduh panduan konsumsi kopi kantor, memiliki tim 20 orang, dan ingin menerima contoh paket. Konteks kecil itu membuat percakapan jauh lebih tepat." },
    { type: "paragraph", text: "Sepanjang buku ini kita akan mengikuti perjalanan orang, bukan perjalanan pesan. Stranger belum mengenal bisnis. Audience mulai melihat konten. Lead memberi sinyal dan izin. Nurtured lead memperoleh edukasi yang relevan. Conversation terjadi ketika ada respons dua arah. Sebagian menjadi customer, kemudian repeat customer, bahkan advocate yang merekomendasikan. Setiap tahap membutuhkan tujuan, pesan, dan ukuran keberhasilan yang berbeda." },
    { type: "subhead", text: "Gambaran besar perjalanan" },
    { type: "flow", items: ["Stranger", "Audience", "Lead", "Nurtured Lead", "Conversation", "Customer", "Repeat Customer", "Advocate"] },
    { type: "paragraph", text: "Alur ini bukan tangga yang selalu lurus. Seseorang dapat berhenti, kembali, atau berpindah lebih cepat karena kebutuhannya mendesak. Tugas sistem bukan memaksa semua orang membeli hari ini, melainkan menyediakan langkah berikutnya yang jelas. Marketing menghasilkan dan memahami lead; nurturing membangun kesiapan; manusia mengambil alih ketika dibutuhkan; pengalaman produk menjaga hubungan setelah transaksi." },
    { type: "subhead", text: "Cara menggunakan buku ini" },
    { type: "list", items: ["Baca berurutan untuk memahami sistem dari lead generation sampai conversion.", "Gunakan contoh sebagai ilustrasi, lalu sesuaikan dengan bisnis, pelanggan, dan kapasitas Anda.", "Kerjakan bagian ‘Aksi bab ini’ sebelum berpindah jika Anda sedang membangun sistem nyata.", "Nilai kualitas dari relevansi dan kemajuan journey, bukan hanya dari besarnya database.", "Pertahankan permission, konteks, dan pilihan penerima di setiap tahap."] },
    { type: "subhead", text: "Peta isi pembuka" },
    { type: "list", items: ["Kenapa buku ini ditulis", "Kesalahan memahami WhatsApp Marketing", "WhatsApp bukan alat mencari leads", "WhatsApp adalah alat untuk melakukan follow-up terhadap leads", "Dari database nomor menuju database calon customer"] }
  ]
};

window.EBOOK_PARTS_1_3_EXPANDED = [
  {
    id: "bagian-1", number: "01", title: "Database Nomor Bukan Leads", accent: "Signal vs noise",
    chapters: [
      {
        number: 1,
        title: "Kesalahan Besar Marketing WhatsApp",
        summary: "Nomor WhatsApp hanyalah alamat kontak; ia baru bernilai sebagai lead ketika ada minat, izin, dan konteks yang dapat dipakai untuk tindak lanjut.",
        blocks: [
          { type: "subhead", text: "Nomor tidak sama dengan lead" },
          { type: "paragraph", text: "Memiliki nomor WhatsApp bukan berarti memiliki leads. Nomor menjawab pertanyaan ‘bagaimana menghubungi seseorang’, sedangkan lead menjawab ‘mengapa orang ini relevan untuk dihubungi’. Lead biasanya meninggalkan jejak konteks: ia meminta katalog, mendaftar webinar, mengisi assessment, bertanya tentang produk, atau secara jelas memilih menerima informasi lanjutan. Tanpa jejak tersebut, bisnis tidak mengetahui kebutuhan, ekspektasi, ataupun waktu yang tepat untuk berbicara." },
          { type: "paragraph", text: "Database besar belum tentu database bernilai. Sepuluh ribu nomor tanpa sumber dan minat bisa menghasilkan lebih banyak pekerjaan daripada seratus lead yang tersegmentasi. Tim harus menebak pesan, produk, dan timing; respons sulit dianalisis; reputasi brand ikut dipertaruhkan. Database bernilai bukan yang paling ramai, melainkan yang membantu bisnis mengambil keputusan tindak lanjut dengan masuk akal." },
          { type: "subhead", text: "Mengapa scraping bukan lead generation" },
          { type: "paragraph", text: "Membeli, mengambil, atau scraping nomor berarti mengumpulkan data kontak dari daftar pihak lain, halaman publik, atau proses otomatis. Aktivitas itu tidak menciptakan minat. Ia juga tidak menjelaskan apakah pemilik nomor ingin mendengar dari bisnis Anda. Lead generation yang benar justru merancang pertukaran nilai: orang menerima informasi, alat, akses, atau bantuan; bisnis menerima data serta izin untuk melanjutkan komunikasi sesuai konteks tersebut." },
          { type: "paragraph", text: "Risiko menghubungi orang tanpa konteks muncul pada detik pertama. Penerima bertanya, ‘Dapat nomor saya dari mana?’ Alih-alih membahas masalah yang bisa diselesaikan, bisnis harus membela alasan mengirim pesan. Pesan yang terlalu sering atau tidak relevan membuat penerima mengabaikan, memblokir, atau memiliki kesan buruk terhadap brand. Marketing pun bergeser dari membantu orang mengambil keputusan menjadi gangguan yang menghabiskan perhatian." },
          { type: "subhead", text: "Contoh praktis" },
          { type: "paragraph", text: "Bayangkan vendor katering kantor. Daftar 5.000 nomor dari direktori bisnis tidak memberi tahu kantor mana yang butuh makan siang rutin. Sebaliknya, vendor menawarkan kalkulator kebutuhan konsumsi rapat. Pengguna memasukkan jumlah peserta, frekuensi acara, dan kisaran anggaran, kemudian memilih menerima contoh menu. Output kalkulator membantu pengguna; inputnya membantu vendor memahami peluang. Pesan berikutnya dapat merujuk pada kebutuhan 40 porsi dan anggaran yang dipilih—bukan promosi umum." },
          { type: "subhead", text: "Kesalahan yang perlu dihindari" },
          { type: "list", items: ["Menganggap semua kontak memiliki minat yang sama.", "Menyimpan nomor tanpa sumber, tanggal, atau alasan opt-in.", "Mengukur keberhasilan hanya dari jumlah nomor yang terkumpul.", "Langsung mengirim promo sebelum menjelaskan konteks.", "Terus menghubungi orang yang tidak merespons tanpa menilai relevansi."] },
          { type: "subhead", text: "Aksi bab ini" },
          { type: "list", items: ["Ambil 20 kontak terbaru dan tandai sumber serta tindakan yang membuat mereka masuk.", "Pisahkan kontak yang memiliki izin dan konteks dari nomor yang sekadar tersimpan.", "Tulis satu kalimat konteks yang dapat dipahami penerima pada pesan pertama.", "Hentikan penambahan database dari sumber yang tidak menghasilkan minat nyata."] },
          { type: "subhead", text: "Peta konsep bab" },
          { type: "list", items: ["Memiliki nomor WhatsApp bukan berarti memiliki leads", "Database besar belum tentu database bernilai", "Mengapa membeli, mengambil, atau scraping nomor bukan strategi lead generation", "Risiko menghubungi orang tanpa konteks", "Dari marketing menjadi gangguan"] }
        ]
      },
      {
        number: 2,
        title: "Sebenarnya Apa Itu Leads?",
        summary: "Lead adalah seseorang yang telah menunjukkan minat dan membuka jalur tindak lanjut; istilah lain menandai tingkat hubungan, kecocokan, serta kesiapan membeli.",
        blocks: [
          { type: "subhead", text: "Delapan status, delapan kebutuhan" },
          { type: "paragraph", text: "Stranger adalah orang yang belum mengenal bisnis. Audience adalah orang yang sudah melihat konten, toko, iklan, atau acara Anda, tetapi belum memberikan identitas dan izin untuk ditindaklanjuti. Ketika seorang audience mengisi form, memulai chat dengan maksud tertentu, mendaftar acara, atau meminta materi dan bersedia menerima komunikasi lanjutan, ia menjadi lead. Perubahan pentingnya bukan sekadar Anda mengetahui nomor mereka; sekarang ada tindakan yang menunjukkan minat." },
          { type: "paragraph", text: "Prospect adalah lead yang secara umum cocok dengan pasar sasaran. Qualified Lead lebih spesifik lagi: kebutuhan, kemampuan, kewenangan, atau timing-nya memenuhi kriteria yang dibuat bisnis. Sebuah studio foto dapat memiliki lead yang meminta daftar harga. Jika orang tersebut mencari fotografer untuk tanggal yang tersedia, menyukai gaya studio, dan memiliki anggaran yang sesuai, ia dapat dikategorikan qualified. Kriteria selalu bergantung pada model bisnis, bukan label universal." },
          { type: "paragraph", text: "Customer sudah melakukan transaksi. Repeat Customer membeli kembali, memperpanjang, atau memakai layanan berikutnya. Advocate melangkah lebih jauh: ia dengan sukarela merekomendasikan, memberi ulasan, membuat rujukan, atau membela pengalaman positifnya. Advocate tidak boleh dipandang sebagai saluran promosi gratis semata. Ia lahir dari hasil dan pengalaman yang layak diceritakan." },
          { type: "flow", items: ["Stranger", "Audience", "Lead", "Prospect", "Qualified Lead", "Customer", "Repeat Customer", "Advocate"] },
          { type: "subhead", text: "Cara memakai status ini" },
          { type: "paragraph", text: "Status membantu menentukan next action. Stranger membutuhkan alasan untuk memperhatikan. Audience membutuhkan tawaran langkah kecil. Lead membutuhkan pemenuhan janji dan follow-up. Prospect perlu edukasi yang sesuai masalahnya. Qualified Lead perlu percakapan penjualan yang cepat dan jelas. Customer membutuhkan onboarding dan hasil. Repeat Customer perlu pengalaman yang konsisten, sedangkan advocate perlu cara yang mudah dan pantas untuk berbagi." },
          { type: "paragraph", text: "Perbedaan database kontak dengan database leads terletak pada metadata dan kegunaannya. Database kontak mungkin hanya menyimpan nama dan nomor. Database leads menambahkan sumber, minat, permission, tanggal masuk, tindakan terakhir, tahap journey, serta pemilik follow-up. Data secukupnya ini memungkinkan segmentasi tanpa berubah menjadi proyek administrasi yang berat." },
          { type: "subhead", text: "Contoh sederhana" },
          { type: "paragraph", text: "Sebuah tempat kursus bahasa mengunggah video tips wawancara. Penonton adalah audience. Orang yang mengunduh worksheet latihan menjadi lead. Lead yang menyatakan akan wawancara dalam 30 hari, membutuhkan kelas privat, dan cocok dengan jadwal menjadi qualified lead. Setelah mendaftar ia menjadi customer; jika mengambil modul lanjutan ia repeat customer; jika kemudian mengajak rekan sekantor melalui referral, ia berperan sebagai advocate." },
          { type: "subhead", text: "Kesalahan yang perlu dihindari" },
          { type: "list", items: ["Memberi status qualified hanya karena seseorang membalas chat.", "Membiarkan status lama meskipun perilaku lead berubah.", "Menganggap setiap follower sebagai lead.", "Berhenti berkomunikasi setelah transaksi dan kehilangan repeat serta advocacy.", "Mengumpulkan data yang tidak pernah dipakai untuk keputusan."] },
          { type: "subhead", text: "Aksi bab ini" },
          { type: "list", items: ["Definisikan satu kalimat untuk lead dan qualified lead di bisnis Anda.", "Tentukan tiga kriteria qualification yang bisa diamati.", "Petakan lima kontak nyata ke tahap journey tanpa memaksakan semuanya sebagai prospect.", "Tulis next action untuk setiap tahap."] },
          { type: "subhead", text: "Peta konsep bab" },
          { type: "list", items: ["Stranger", "Audience", "Lead", "Prospect", "Qualified Lead", "Customer", "Repeat Customer", "Advocate", "Perbedaan database kontak dengan database leads"] }
        ]
      },
      {
        number: 3,
        title: "Era Blast Sudah Berubah",
        summary: "Saat perhatian terbatas dan pilihan melimpah, relevansi, konteks, dan timing mengalahkan strategi mengirim pesan yang sama sebanyak-banyaknya.",
        blocks: [
          { type: "subhead", text: "Dari volume menuju relevansi" },
          { type: "paragraph", text: "Pendekatan blast sebanyak-banyaknya semakin tidak efektif karena pesan Anda bersaing dengan chat kerja, keluarga, komunitas, notifikasi aplikasi, konten, dan banyak penawaran lain. Menambah volume tidak otomatis menambah perhatian. Ketika pesan yang sama dikirim kepada orang dengan kebutuhan berbeda, sebagian besar penerima harus bekerja sendiri untuk mencari tahu apakah pesan itu relevan. Biasanya mereka memilih jalan tercepat: melewatinya." },
          { type: "paragraph", text: "Attention semakin mahal bukan hanya soal harga iklan. Bisnis juga membayar lewat waktu produksi konten, tenaga follow-up, kejenuhan penerima, dan kesempatan yang hilang. Satu pesan yang tidak tepat mengurangi peluang pesan berikutnya dibaca. Karena itu perhatian harus diperlakukan sebagai pinjaman: setiap interaksi perlu mengembalikan nilai dalam bentuk kejelasan, kegunaan, atau kemajuan." },
          { type: "paragraph", text: "Customer semakin selektif karena mereka dapat membandingkan lebih cepat. Mereka memeriksa ulasan, melihat alternatif, menunda keputusan, dan mengabaikan klaim umum. Ini bukan berarti manusia tidak ingin menerima penawaran. Mereka ingin penawaran yang masuk akal bagi situasinya, menjelaskan manfaat secara konkret, dan datang setelah cukup rasa percaya." },
          { type: "subhead", text: "Konteks adalah bahan bakar pesan" },
          { type: "paragraph", text: "Relevansi menjadi lebih penting daripada volume. Relevansi lahir dari kecocokan antara siapa penerimanya, masalah yang sedang dipikirkan, tahapan keputusan, pesan yang dikirim, serta tindakan yang diminta. Marketing 2026–2027 membutuhkan konteks tersebut. Tanggal bukan satu-satunya pemicu; perilaku seperti mengunduh panduan, memilih kategori, menghadiri webinar, atau kembali melihat halaman produk dapat menjadi dasar journey yang lebih tepat." },
          { type: "paragraph", text: "Misalnya toko perlengkapan bayi memiliki lead orang tua hamil, orang tua bayi baru lahir, dan pembeli hadiah. Blast promo botol susu kepada semua orang mengabaikan konteks. Segmentasi sederhana memungkinkan seri persiapan kelahiran untuk kelompok pertama, panduan pemilihan ukuran untuk kelompok kedua, dan rekomendasi gift set untuk kelompok ketiga. Jumlah pesan mungkin lebih sedikit, tetapi setiap pesan mempunyai alasan." },
          { type: "subhead", text: "Bukan berarti broadcast selalu salah" },
          { type: "paragraph", text: "Broadcast masih berguna untuk pengumuman yang memang berlaku luas—misalnya perubahan jam operasional kepada customer aktif—selama penerima mengharapkannya. Yang berubah adalah menjadikan blast sebagai strategi utama tanpa segmentasi, permission, dan tujuan. Gunakan broadcast sebagai format distribusi; jangan jadikan keseragaman sebagai cara berpikir." },
          { type: "subhead", text: "Kesalahan yang perlu dihindari" },
          { type: "list", items: ["Menaikkan frekuensi ketika respons turun tanpa memeriksa relevansi.", "Menggunakan satu CTA untuk cold, warm, dan hot lead.", "Menganggap personalisasi hanya menambahkan nama depan.", "Mengirim berdasarkan kalender internal tanpa melihat journey penerima.", "Menilai keberhasilan dari delivered message saja."] },
          { type: "subhead", text: "Aksi bab ini" },
          { type: "list", items: ["Ambil satu broadcast terakhir dan tandai kelompok yang benar-benar membutuhkan pesan itu.", "Tulis ulang pesan untuk dua konteks penerima yang berbeda.", "Pilih satu sinyal perilaku sebagai pemicu follow-up.", "Kurangi satu pesan berulang yang tidak memberi nilai baru."] },
          { type: "subhead", text: "Peta konsep bab" },
          { type: "list", items: ["Mengapa pendekatan blast sebanyak-banyaknya semakin tidak efektif", "Attention semakin mahal", "Customer semakin selektif", "Relevansi menjadi lebih penting daripada volume", "Marketing 2026–2027 membutuhkan konteks"] }
        ]
      },
      {
        number: 4,
        title: "Permission Is the New Currency",
        summary: "Permission adalah persetujuan yang disertai ekspektasi; nilainya muncul ketika bisnis menggunakan izin itu sesuai konteks untuk membangun trust sebelum transaksi.",
        blocks: [
          { type: "subhead", text: "Izin bukan kotak centang kosong" },
          { type: "paragraph", text: "Permission atau izin adalah aset karena ia membuka kesempatan untuk melanjutkan hubungan tanpa harus memulai dari nol setiap saat. Namun izin bukan kepemilikan atas perhatian. Seseorang yang meminta reminder webinar belum tentu ingin menerima promo semua produk setiap hari. Nilai permission bergantung pada seberapa jelas orang memahami apa yang akan diterima dan seberapa konsisten bisnis menjaga janji tersebut." },
          { type: "paragraph", text: "Opt-in adalah tindakan seseorang memilih masuk. Bentuknya bisa mencentang persetujuan, mengirim kata kunci melalui chat, mendaftar kelas, atau meminta penawaran. Opt-in yang baik menjelaskan pengirim, jenis konten, kanal, dan next action. Jika seseorang mengisi form konsultasi interior, misalnya, ia wajar mengharapkan konfirmasi jadwal dan materi persiapan; ia belum tentu mengharapkan promosi properti dari partner yang tidak disebutkan." },
          { type: "subhead", text: "Ekspektasi membentuk relevansi" },
          { type: "paragraph", text: "Ekspektasi calon customer adalah gambaran mental tentang apa yang terjadi setelah mereka menyerahkan kontak. Terlambat mengirim lead magnet, mengganti topik secara tiba-tiba, atau meningkatkan frekuensi tanpa alasan merusak ekspektasi. Sebaliknya, pesan pertama yang menyebut sumber, memenuhi janji, dan memberi pilihan langkah berikutnya memperkuat rasa aman." },
          { type: "paragraph", text: "Context-based marketing menggunakan sumber dan perilaku lead sebagai dasar komunikasi. Lead yang mengikuti webinar pajak UMKM dapat menerima rangkuman, checklist dokumen, lalu undangan konsultasi. Lead yang hanya mengunduh template invoice membutuhkan jalur berbeda. Relevansi pesan bukan berarti mengetahui semua hal tentang seseorang; cukup gunakan data yang memang ia berikan untuk membantu keputusan berikutnya." },
          { type: "subhead", text: "Trust sebelum transaksi" },
          { type: "paragraph", text: "Trust tumbuh ketika ucapan, tindakan, dan hasil kecil selaras. Anda mengirim apa yang dijanjikan, tidak menyamarkan promosi sebagai edukasi, menjawab dengan jelas, dan menghormati pilihan penerima. Dalam jasa renovasi, calon klien mungkin belum siap meminta quotation. Panduan menyusun scope, contoh proses kerja, dan checklist kunjungan lokasi bisa membangun trust tanpa mendesaknya mengambil keputusan besar." },
          { type: "paragraph", text: "Permission juga perlu dapat dikelola. Simpan sumber dan waktu opt-in, segmentasikan topik, sediakan jalan untuk berhenti, dan jangan memperluas penggunaan data diam-diam. Prinsip praktisnya sederhana: jika penerima melihat pesan ini, apakah ia langsung memahami mengapa mendapatkannya? Jika jawabannya tidak, konteks perlu diperbaiki." },
          { type: "subhead", text: "Kesalahan yang perlu dihindari" },
          { type: "list", items: ["Menganggap satu opt-in berlaku untuk semua topik dan selamanya.", "Menyembunyikan ekspektasi follow-up di balik formulir yang tidak jelas.", "Mengirim promo sebelum deliverable yang dijanjikan.", "Memakai data pribadi yang tidak diperlukan untuk personalisasi semu.", "Membuat penerima sulit menghentikan komunikasi."] },
          { type: "subhead", text: "Aksi bab ini" },
          { type: "list", items: ["Tulis ulang kalimat opt-in agar menjelaskan manfaat dan follow-up.", "Audit apakah pesan pertama menyebut konteks sumber lead.", "Catat topik permission, bukan hanya status ya atau tidak.", "Buat satu cara sederhana bagi penerima untuk mengubah atau menghentikan komunikasi."] },
          { type: "subhead", text: "Peta konsep bab" },
          { type: "list", items: ["Mengapa izin adalah aset", "Opt-in", "Ekspektasi calon customer", "Context-based marketing", "Relevansi pesan", "Trust sebelum transaksi"] }
        ]
      },
      {
        number: 8,
        title: "Search-to-Lead",
        summary: "Search-to-Lead menangkap orang yang sedang aktif mencari jawaban atau penyedia, lalu mengubah intent tersebut menjadi langkah yang bisa ditindaklanjuti.",
        blocks: [
          { type: "subhead", text: "Menangkap permintaan yang sudah ada" },
          { type: "paragraph", text: "Search-to-Lead dimulai ketika seseorang mengetik kebutuhan, masalah, lokasi, atau nama kategori ke mesin pencari dan kanal pencarian lain. Berbeda dari social traffic yang sering menemukan konten saat sedang menjelajah, search traffic biasanya membawa pertanyaan lebih eksplisit. Tugas bisnis adalah hadir pada query yang tepat, menjawabnya, lalu menyediakan next action yang sebanding dengan intent." },
          { type: "paragraph", text: "Google Search dapat mengarahkan pencari ke artikel, halaman layanan, katalog, atau landing page. SEO adalah proses membuat halaman berguna dan mudah dipahami mesin pencari untuk query yang relevan; ia bukan sekadar memasukkan kata kunci. Google Maps membantu pencarian lokal seperti ‘laundry sepatu dekat sini’. Informasi kategori, alamat, jam, foto, ulasan, dan tombol kontak memengaruhi apakah pencari melanjutkan." },
          { type: "paragraph", text: "Marketplace juga berfungsi sebagai search engine produk. Pengguna membandingkan model, spesifikasi, harga, dan reputasi penjual. Direktori membantu pencarian penyedia berdasarkan bidang atau wilayah. Di masing-masing kanal, ikuti jalur yang tersedia: optimalkan listing, jawab pertanyaan, dan arahkan hanya ke langkah yang memang diizinkan oleh kanal serta diharapkan pengguna." },
          { type: "subhead", text: "Buying intent bukan satu tingkat" },
          { type: "paragraph", text: "Query ‘cara memilih AC untuk kamar’ menunjukkan kebutuhan edukasi. ‘Harga pasang AC 1 PK Makassar’ menunjukkan perbandingan penyedia yang lebih dekat ke transaksi. Keduanya bernilai, tetapi offer berbeda. Query edukasi dapat diarahkan ke calculator kapasitas dan panduan. Query komersial dapat diarahkan ke form survei, estimasi, atau chat dengan informasi lokasi dan ukuran ruangan." },
          { type: "paragraph", text: "Search traffic vs social traffic juga berbeda pada creative. Di search, relevansi antara query, judul halaman, isi, dan CTA sangat penting. Di social, Anda lebih dulu harus memperoleh perhatian dan membantu audience menyadari masalah. Social dapat menciptakan demand; search menangkap demand. Bisnis yang memakai keduanya dapat menumbuhkan minat sekaligus tersedia saat keputusan mulai aktif." },
          { type: "subhead", text: "Contoh praktis" },
          { type: "paragraph", text: "Bengkel spesialis transmisi membuat halaman ‘gejala CVT perlu diperiksa’ dan profil Maps yang lengkap. Pengunjung dapat mengisi diagnostic singkat: jenis mobil, gejala, kapan muncul, dan lokasi. Output memberi daftar pemeriksaan awal, bukan diagnosis pasti, lalu menawarkan jadwal inspeksi. Bengkel mendapat konteks yang membantu persiapan, sementara pengguna mendapat arah tanpa janji hasil yang dibuat-buat." },
          { type: "subhead", text: "Kesalahan yang perlu dihindari" },
          { type: "list", items: ["Mengejar keyword ramai yang tidak berhubungan dengan layanan.", "Mengirim semua search traffic ke homepage umum.", "Menganggap setiap query memiliki kesiapan membeli yang sama.", "Membuat halaman tipis yang hanya mengulang kata kunci.", "Tidak mengukur query atau listing mana yang menghasilkan qualified lead."] },
          { type: "subhead", text: "Aksi bab ini" },
          { type: "list", items: ["Kumpulkan sepuluh query nyata yang digunakan customer.", "Kelompokkan menjadi informational, local, dan commercial intent.", "Cocokkan satu halaman serta satu CTA untuk tiap kelompok.", "Pastikan hasil pencarian lokal atau listing menjawab informasi keputusan dasar."] },
          { type: "subhead", text: "Peta konsep bab" },
          { type: "list", items: ["Google Search", "SEO", "Google Maps", "Marketplace", "Direktori", "Menangkap calon customer dengan buying intent", "Search traffic vs social traffic"] }
        ]
      },
      {
        number: 9,
        title: "Ads-to-Lead",
        summary: "Ads-to-Lead membeli distribusi untuk offer tertentu; kualitasnya dinilai dari lead yang relevan dan kemajuan funnel, bukan sekadar klik atau biaya lead murah.",
        blocks: [
          { type: "subhead", text: "Iklan mempercepat distribusi" },
          { type: "paragraph", text: "Ads-to-Lead menggunakan media berbayar untuk menampilkan offer kepada audience yang dipilih. Meta Ads membantu menjangkau berdasarkan sinyal audience dan creative visual. TikTok Ads bertumpu pada konten vertikal yang cepat dipahami. Google Ads dapat menangkap query dengan intent aktif. Pemilihan kanal seharusnya mengikuti tempat audience mencari atau menemukan solusi, bukan sekadar kanal yang sedang ramai." },
          { type: "paragraph", text: "Click-to-WhatsApp membawa pengguna dari iklan langsung ke chat. Format ini cocok bila keputusan memerlukan percakapan cepat, tetapi pesan pembuka perlu mengingatkan konteks iklan dan mengumpulkan informasi penting. Lead Form menyimpan data di dalam platform sehingga hambatan rendah; konsekuensinya, follow-up dan qualification harus kuat. Landing Page memberi ruang lebih luas untuk menjelaskan offer, bukti, serta ekspektasi sebelum form." },
          { type: "subhead", text: "Apa yang sebenarnya dibeli" },
          { type: "paragraph", text: "Iklan membeli kesempatan dilihat dan diklik, bukan membeli customer. Sistem tetap membutuhkan offer yang bernilai, capture yang jelas, database, dan follow-up. Input berupa budget, audience, creative, pesan, dan destination. Proses platform mendistribusikan iklan dan mengoptimalkan sinyal. Output awal dapat berupa impressions, clicks, chats, atau form submissions; hasil bisnis baru terlihat setelah qualification dan conversion." },
          { type: "paragraph", text: "Cost per Lead atau CPL dihitung dengan membagi biaya iklan dengan jumlah lead yang memenuhi definisi capture. Jika biaya Rp1.000.000 menghasilkan 100 lead, CPL-nya Rp10.000. Angka ini belum menyatakan kualitas. Bandingkan lebih jauh: berapa yang merespons, qualified, membuat appointment, dan membeli. Sumber dengan CPL Rp30.000 dapat lebih menguntungkan daripada Rp8.000 jika menghasilkan lebih banyak customer sesuai target." },
          { type: "subhead", text: "Contoh praktis" },
          { type: "paragraph", text: "Penyedia software kasir mengiklankan assessment ‘Seberapa rapi operasional tokomu?’ bukan langsung meminta demo kepada semua orang. Form menanyakan jumlah cabang, pencatatan saat ini, dan masalah utama. Hasil memberi rekomendasi awal. Lead dengan satu toko dan kebutuhan edukasi masuk nurturing; lead multi-cabang yang sedang mengganti sistem dapat ditawarkan demo. Contoh ini ilustratif dan kriterianya harus diuji dari data bisnis nyata." },
          { type: "subhead", text: "Kesalahan yang perlu dihindari" },
          { type: "list", items: ["Mengoptimalkan creative untuk klik sensasional yang tidak cocok dengan offer.", "Membiarkan lead form tanpa konfirmasi atau follow-up cepat.", "Membandingkan CPL antar-channel tanpa melihat kualitas.", "Mengubah audience, creative, dan landing page bersamaan.", "Tidak menyampaikan apa yang terjadi setelah pengguna mengirim data."] },
          { type: "subhead", text: "Aksi bab ini" },
          { type: "list", items: ["Pilih satu outcome funnel setelah lead, misalnya qualified chat atau appointment.", "Buat jalur terpisah untuk Click-to-WhatsApp, Lead Form, atau Landing Page yang dipakai.", "Hitung CPL dan cost per qualified lead.", "Baca sepuluh percakapan atau form untuk menilai kecocokan promise iklan."] },
          { type: "subhead", text: "Peta konsep bab" },
          { type: "list", items: ["Meta Ads", "TikTok Ads", "Google Ads", "Click-to-WhatsApp", "Lead Form", "Landing Page", "Mengukur Cost per Lead", "Jangan sekadar mengejar leads murah"] }
        ]
      },
      {
        number: 10,
        title: "Community-to-Lead",
        summary: "Community-to-Lead mengubah partisipasi dalam acara atau kelompok menjadi hubungan berizin melalui pengalaman bersama, pencatatan konteks, dan next action yang jelas.",
        blocks: [
          { type: "subhead", text: "Dari kehadiran menjadi konteks" },
          { type: "paragraph", text: "Komunitas menciptakan sesuatu yang sulit diperoleh dari iklan singkat: perhatian dalam durasi lebih panjang, interaksi, dan pengalaman bersama. Webinar adalah sesi daring yang biasanya berfokus pada topik. Seminar lebih banyak menyampaikan wawasan. Workshop menambahkan praktik dan output. Kelas gratis memberi struktur belajar, sedangkan challenge mengajak peserta menyelesaikan tindakan selama beberapa hari. Masing-masing menghasilkan sinyal minat yang berbeda." },
          { type: "paragraph", text: "WhatsApp Group dan Telegram dapat menjadi ruang koordinasi, diskusi, atau distribusi materi. Grup bukan izin otomatis untuk memindahkan nomor anggota ke promosi pribadi. Jelaskan fungsi grup, aturan, durasi, dan pilihan follow-up. Komunitas jangka panjang berpusat pada identitas atau tujuan bersama; nilainya harus tetap ada meski peserta belum membeli." },
          { type: "paragraph", text: "Event offline menambahkan pertemuan langsung. Peserta dapat mendaftar melalui form atau QR code sehingga bisnis mengetahui topik, sesi, dan izin komunikasi. Jangan menunggu acara selesai untuk memikirkan capture. Rancang perjalanan: undangan, registrasi, reminder, pengalaman utama, materi lanjutan, feedback, lalu next action yang relevan." },
          { type: "subhead", text: "Mengubah peserta menjadi leads" },
          { type: "paragraph", text: "Peserta menjadi lead ketika identitas, minat, dan permission tercatat—bukan hanya karena mereka berada di ruangan yang sama. Gunakan pertanyaan registrasi secukupnya, misalnya peran, tantangan utama, dan tujuan mengikuti acara. Setelah acara, segmentasikan berdasarkan kehadiran, pertanyaan, atau pilihan topik. Orang yang tidak hadir membutuhkan rekaman atau jadwal lain; peserta aktif dapat menerima worksheet atau undangan sesi lanjutan." },
          { type: "paragraph", text: "Contoh: toko bahan baking menyelenggarakan workshop roti sourdough. Pendaftaran mencatat tingkat pengalaman dan peralatan yang sudah dimiliki. Pemula menerima panduan starter dan daftar alat dasar. Peserta yang sudah rutin membuat roti mendapat materi mengatasi kegagalan fermentasi. Penawaran produk mengikuti kebutuhan tersebut, bukan katalog penuh. Semua contoh adalah ilustrasi; formulir dan komunikasi harus sesuai kapasitas acara." },
          { type: "subhead", text: "Kesalahan yang perlu dihindari" },
          { type: "list", items: ["Mengukur sukses hanya dari jumlah pendaftar, bukan peserta dan next action.", "Memasukkan semua peserta ke grup tanpa ekspektasi jelas.", "Mengubah sesi edukasi menjadi presentasi produk panjang.", "Mengirim materi yang sama kepada hadir dan tidak hadir tanpa konteks.", "Membiarkan pertanyaan berniat tinggi tidak diteruskan ke tim."] },
          { type: "subhead", text: "Aksi bab ini" },
          { type: "list", items: ["Pilih satu format community sesuai hasil yang ingin peserta capai.", "Rancang perjalanan sebelum, selama, dan sesudah acara.", "Tambahkan dua pertanyaan registrasi yang berguna untuk segmentasi.", "Tentukan next action berbeda untuk peserta aktif, pasif, dan tidak hadir."] },
          { type: "subhead", text: "Peta konsep bab" },
          { type: "list", items: ["Webinar", "Seminar", "Workshop", "WhatsApp Group", "Telegram", "Kelas gratis", "Challenge", "Komunitas", "Event offline", "Mengubah peserta menjadi leads"] }
        ]
      },
      {
        number: 11,
        title: "Partnership-to-Lead",
        summary: "Partnership-to-Lead meminjam kepercayaan dan distribusi partner tanpa mengorbankan permission; audience harus memahami siapa berkomunikasi dan untuk tujuan apa.",
        blocks: [
          { type: "subhead", text: "Bentuk partnership dan fungsinya" },
          { type: "paragraph", text: "Affiliate mempromosikan offer dan menerima kompensasi ketika tindakan yang disepakati terjadi. Referral biasanya lahir dari rekomendasi customer, rekan, atau partner kepada orang yang dianggap cocok. Joint webinar menggabungkan keahlian dan audience dua pihak. Strategic partnership lebih luas: dua bisnis menggabungkan produk, distribusi, atau pengalaman untuk menciptakan nilai yang sulit dibuat sendiri." },
          { type: "paragraph", text: "Influencer membawa perhatian dan kepercayaan dari audience-nya; kecocokan topik serta gaya lebih penting daripada jumlah follower semata. Reseller menjual kembali produk dan membutuhkan materi, aturan lead ownership, serta proses handoff yang jelas. Community collaboration bekerja ketika offer membantu tujuan komunitas, bukan sekadar menumpang menyebarkan promosi." },
          { type: "subhead", text: "Permission tidak boleh hilang di tengah" },
          { type: "paragraph", text: "Database sharing yang tetap permission-based bukan mengirim spreadsheet anggota kepada partner. Rancang halaman pendaftaran yang menjelaskan pihak yang akan menghubungi, manfaat yang diterima, dan pilihan persetujuan. Alternatif lain: partner mengirim invitation kepada audience sendiri, lalu orang yang tertarik opt-in langsung ke bisnis tujuan. Dengan demikian, perpindahan hubungan terjadi secara sadar." },
          { type: "paragraph", text: "Tetapkan juga sumber dan attribution. Kode referral, link berbeda, atau field sumber membantu menilai partner bukan hanya dari volume, tetapi dari qualified lead dan customer. Sepakati siapa memenuhi janji awal, siapa menindaklanjuti, berapa lama, dan bagaimana pertanyaan ditangani. Partnership yang kabur sering menghasilkan pengalaman terputus meski jumlah lead terlihat bagus." },
          { type: "subhead", text: "Contoh praktis" },
          { type: "paragraph", text: "Jasa pembukuan berpartner dengan coworking space untuk kelas ‘Menutup Buku Bulanan Tanpa Panik’. Coworking mengundang member; halaman registrasi menyebut kedua pihak. Peserta memilih apakah ingin menerima template dari pembicara dan informasi acara lanjutan. Setelah kelas, jasa pembukuan mengirim template serta diagnostic sederhana. Coworking tidak menyerahkan seluruh daftar member, dan peserta yang tidak memilih follow-up tidak dimasukkan ke campaign." },
          { type: "subhead", text: "Kesalahan yang perlu dihindari" },
          { type: "list", items: ["Memilih partner hanya dari ukuran audience.", "Menukar database mentah tanpa opt-in yang jelas.", "Tidak menyepakati pesan, handoff, dan tanggung jawab follow-up.", "Memberi insentif affiliate hanya untuk volume tanpa menilai kualitas.", "Menyembunyikan hubungan komersial yang relevan bagi audience."] },
          { type: "subhead", text: "Aksi bab ini" },
          { type: "list", items: ["Daftar tiga partner dengan audience yang sama tetapi solusi pelengkap.", "Rumuskan nilai untuk audience, partner, dan bisnis Anda.", "Buat alur opt-in yang menyebut pihak serta tujuan komunikasi.", "Tentukan attribution dan ukuran kualitas sebelum kampanye dimulai."] },
          { type: "subhead", text: "Peta konsep bab" },
          { type: "list", items: ["Affiliate", "Referral", "Joint webinar", "Strategic partnership", "Influencer", "Reseller", "Community collaboration", "Database sharing yang tetap permission-based"] }
        ]
      },
      {
        number: 12,
        title: "Offline-to-Online Leads",
        summary: "Offline-to-Online menghubungkan momen fisik dengan database digital melalui ajakan yang kontekstual, capture singkat, dan manfaat yang langsung terasa.",
        blocks: [
          { type: "subhead", text: "Setiap titik fisik dapat menjadi pintu" },
          { type: "paragraph", text: "Aktivitas offline kaya konteks tetapi sering berhenti setelah pertemuan selesai. QR Code menjembatani benda atau lokasi ke halaman, form, chat, atau tool. Kode itu sendiri tidak memberi alasan untuk scan; letakkan promise di dekatnya, misalnya ‘scan untuk panduan ukuran’ atau ‘simpan garansi dan cara perawatan’. Destination harus ramah mobile dan melanjutkan konteks yang sama." },
          { type: "paragraph", text: "Di toko, ajakan dapat ditempatkan dekat kategori produk atau kasir. Booth dapat menawarkan demo, assessment, atau undian yang tetap relevan dengan produk. Seminar dan event menghubungkan registrasi, materi, serta follow-up. Packaging dapat membawa customer ke panduan penggunaan, registrasi garansi, resep, atau repeat order. Brosur dan kartu nama lebih berguna bila mengarah ke resource spesifik daripada homepage umum." },
          { type: "paragraph", text: "Invoice muncul setelah transaksi sehingga cocok untuk onboarding, dukungan, reorder, atau referral—bukan menganggap customer sebagai lead baru tanpa sejarah. Setiap touchpoint harus mempertimbangkan tahap journey. Lead dari kartu nama setelah percakapan konsultasi berbeda dari orang yang memindai poster di ruang publik. Simpan sumber pada link atau pilihan form agar follow-up tidak kehilangan konteks." },
          { type: "subhead", text: "Input, proses, output" },
          { type: "paragraph", text: "Input berupa scan atau entry singkat, ditambah data minimum seperti jenis kebutuhan. Proses melakukan capture, memberi tag sumber, dan mengirim manfaat. Output bagi pengguna bisa berupa menu digital, estimasi, tutorial, tiket, atau reminder. Output bagi bisnis adalah kontak berizin dengan lokasi atau aktivitas asal yang diketahui." },
          { type: "subhead", text: "Contoh praktis" },
          { type: "paragraph", text: "Produsen furnitur menaruh QR code di label meja display: ‘Lihat ukuran, pilihan warna, dan simulasi penempatan’. Pengunjung memilih tipe ruangan dan mengisi ukuran area; halaman memberi rekomendasi konfigurasi. Jika ingin menyimpan hasil, pengguna opt-in melalui WhatsApp. Tim menerima sumber showroom, produk, dimensi, dan warna pilihan, sehingga follow-up dapat mengirim quotation relevan. Orang yang hanya melihat tetap memperoleh informasi tanpa dipaksa menyerahkan data." },
          { type: "subhead", text: "Kesalahan yang perlu dihindari" },
          { type: "list", items: ["Menampilkan QR code tanpa menjelaskan manfaat.", "Mengarahkannya ke halaman desktop yang lambat atau umum.", "Meminta form panjang ketika orang sedang berdiri di booth atau kasir.", "Menggabungkan semua sumber offline dalam satu label.", "Tidak menguji kode, sinyal internet, dan fallback sebelum event."] },
          { type: "subhead", text: "Aksi bab ini" },
          { type: "list", items: ["Petakan toko, booth, packaging, brosur, invoice, kartu nama, seminar, dan event yang benar-benar Anda miliki.", "Pilih satu momen dengan intent tertinggi.", "Pasangkan promise singkat, destination mobile, dan tag sumber.", "Uji seluruh alur dengan ponsel dari posisi pengguna."] },
          { type: "subhead", text: "Peta konsep bab" },
          { type: "list", items: ["QR Code", "Toko", "Booth", "Seminar", "Packaging", "Brosur", "Invoice", "Kartu nama", "Event", "Menghubungkan aktivitas offline ke database digital"] }
        ]
      }
    ]
  },
  {
    id: "bagian-2", number: "02", title: "Cara Mencari Leads di 2026–2027", accent: "Build the machine",
    chapters: [
      {
        number: 5,
        title: "Jangan Berburu Leads, Bangun Lead Machine",
        summary: "Lead machine adalah sistem berulang yang menghubungkan traffic, offer, capture, database, follow-up, dan conversion agar pertumbuhan tidak bergantung pada aksi dadakan.",
        blocks: [
          { type: "subhead", text: "Lead generation sebagai sistem" },
          { type: "paragraph", text: "Berburu leads biasanya bersifat episodik: penjualan sepi, lalu tim mencari daftar kontak, membuat promo mendadak, atau menjalankan iklan tanpa alur lanjut. Lead machine mengubah aktivitas itu menjadi sistem. Setiap komponen memiliki fungsi, input, output, dan ukuran. Jika hasil lemah, Anda dapat menemukan titik yang perlu diperbaiki daripada menambah volume secara membabi buta." },
          { type: "flow", items: ["Traffic", "Offer", "Lead Capture", "Database", "Follow-Up", "Conversion"] },
          { type: "paragraph", text: "Traffic adalah orang yang datang dari konten, search, iklan, partner, event, atau lokasi fisik. Offer di tahap ini bukan selalu diskon atau produk utama; offer adalah alasan untuk melangkah, seperti checklist, demo, sampel, konsultasi, atau informasi harga yang terstruktur. Lead capture adalah mekanisme memperoleh identitas, izin, dan data konteks melalui form, landing page, chat, QR code, atau pendaftaran acara." },
          { type: "paragraph", text: "Database menyimpan lead secara teratur agar tidak tercecer. Minimal ada sumber, minat, waktu masuk, dan status follow-up. Follow-up memenuhi janji, memberi edukasi, mengajak respons, dan mengarahkan lead sesuai kesiapan. Conversion terjadi ketika lead mengambil hasil bisnis yang dituju: memesan, membuat appointment, memulai trial, membayar, atau tindakan lain yang telah didefinisikan." },
          { type: "subhead", text: "Contoh mesin sederhana" },
          { type: "paragraph", text: "Klinik perawatan kulit membuat konten tentang perbedaan kulit kering dan dehidrasi. CTA mengarah ke quiz kebutuhan perawatan. Pengguna menjawab keluhan, rutinitas, dan preferensi jadwal, lalu memilih menerima hasil lewat WhatsApp. Sistem menyimpan sumber serta jawaban, mengirim ringkasan, kemudian menawarkan konsultasi bila hasil menunjukkan kebutuhan yang sesuai. Tim klinik mengambil alih saat pengguna bertanya tentang slot atau biaya. Setiap komponen memperjelas langkah berikutnya." },
          { type: "paragraph", text: "Lead generation harus berjalan terus-menerus karena kebutuhan pasar tidak muncul serempak. Orang yang belum siap minggu ini mungkin mulai mencari bulan depan. Sistem always-on menangkap permintaan ketika muncul, sementara eksperimen berkala memperbaiki offer dan pesan. Terus-menerus bukan berarti terus membombardir; yang selalu hidup adalah jalur masuk dan follow-up yang relevan." },
          { type: "subhead", text: "Kesalahan yang perlu dihindari" },
          { type: "list", items: ["Membeli traffic sebelum offer dan follow-up siap.", "Mengumpulkan lead di banyak tempat tanpa satu pencatatan yang konsisten.", "Menganggap conversion harus selalu berupa pembelian langsung.", "Tidak menetapkan siapa yang menangani reply berkualitas.", "Mengubah seluruh mesin sekaligus sehingga penyebab hasil tidak diketahui."] },
          { type: "subhead", text: "Aksi bab ini" },
          { type: "list", items: ["Gambar enam komponen mesin Anda saat ini.", "Tuliskan input dan output setiap komponen.", "Temukan satu sambungan yang paling sering bocor.", "Tetapkan satu ukuran dan satu perbaikan untuk sambungan tersebut minggu ini."] },
          { type: "subhead", text: "Peta konsep bab" },
          { type: "list", items: ["Lead generation sebagai sistem", "Traffic", "Offer", "Lead capture", "Database", "Follow-up", "Conversion", "Kenapa lead generation harus berjalan terus-menerus"] }
        ]
      },
      {
        number: 6,
        title: "Lead Magnet: Berikan Alasan untuk Masuk ke Database",
        summary: "Lead magnet adalah pertukaran nilai yang membantu calon customer menyelesaikan langkah kecil sekaligus memberi bisnis permission dan konteks untuk follow-up.",
        blocks: [
          { type: "subhead", text: "Apa yang membuat lead magnet bekerja" },
          { type: "paragraph", text: "Lead magnet bukan sekadar file gratis. Ia adalah offer awal yang menjawab masalah spesifik, cepat digunakan, dan berhubungan dengan solusi utama bisnis. Input dari calon lead bisa sesederhana nama, kontak, pilihan topik, atau jawaban singkat. Prosesnya memberi akses atau menghasilkan output. Output harus memiliki manfaat mandiri—bukan hanya brosur penjualan—sekaligus membuka next action yang wajar." },
          { type: "paragraph", text: "Ebook cocok untuk menjelaskan topik yang membutuhkan konteks. Checklist membantu memastikan langkah tidak terlewat. Template memberi struktur siap pakai, sedangkan worksheet memandu pengguna berpikir dan mengisi keputusan sendiri. Calculator menerima angka dan menghasilkan estimasi, misalnya kebutuhan cat berdasarkan luas dinding. Assessment mengumpulkan jawaban lalu memetakan kondisi, seperti tingkat kesiapan digital sebuah toko." },
          { type: "paragraph", text: "Mini course memberikan pembelajaran bertahap; webinar menggabungkan edukasi dan interaksi pada waktu tertentu. Trial memberi pengalaman terbatas terhadap produk. Voucher menurunkan hambatan transaksi dan cocok saat minat sudah lebih dekat ke pembelian. Konsultasi serta demo membutuhkan waktu manusia, sehingga idealnya ditawarkan kepada lead dengan kebutuhan dan fit yang cukup jelas. Tools adalah alat praktis—generator, planner, checker, atau dashboard kecil—yang menghasilkan pekerjaan nyata bagi pengguna." },
          { type: "subhead", text: "Pilih format dari pekerjaan pengguna" },
          { type: "paragraph", text: "Jangan memilih format karena sedang populer. Mulailah dari pekerjaan kecil yang ingin diselesaikan calon customer. Akuntan UMKM dapat menawarkan template arus kas jika audiens butuh pencatatan, assessment kesehatan pembukuan jika mereka belum tahu masalahnya, atau konsultasi jika mereka sudah memiliki data dan ingin keputusan. Satu masalah dapat membutuhkan format berbeda berdasarkan tingkat awareness." },
          { type: "paragraph", text: "Contoh produk fisik: toko tanaman menjual paket untuk apartemen. Lead magnet ‘Pilih Tanaman untuk Ruanganmu’ meminta input cahaya, waktu perawatan, dan ada tidaknya hewan peliharaan. Proses mencocokkan kondisi dengan kategori; output adalah tiga tipe tanaman dan panduan perawatan dasar. Setelah opt-in, follow-up dapat menawarkan katalog yang hanya berisi opsi relevan. Contoh ini ilustratif; rekomendasi nyata tetap perlu disesuaikan dengan produk dan keamanan." },
          { type: "subhead", text: "Kesalahan yang perlu dihindari" },
          { type: "list", items: ["Membuat materi terlalu luas agar terlihat lengkap.", "Meminta terlalu banyak data sebelum nilai diberikan.", "Memilih voucher untuk audience yang belum memahami produk.", "Mengirim file lalu tidak menyediakan next action.", "Membuat konsultasi gratis tanpa qualification sehingga kapasitas habis."] },
          { type: "subhead", text: "Aksi bab ini" },
          { type: "list", items: ["Pilih satu masalah kecil yang muncul sebelum kebutuhan produk utama.", "Tentukan input, proses, output, dan next action lead magnet.", "Pilih satu format yang paling cepat memberi hasil bagi pengguna.", "Uji apakah judul menjelaskan hasil, bukan hanya format."] },
          { type: "subhead", text: "Peta konsep bab" },
          { type: "list", items: ["Ebook", "Checklist", "Template", "Worksheet", "Calculator", "Assessment", "Mini course", "Webinar", "Trial", "Voucher", "Konsultasi", "Demo", "Tools"] }
        ]
      },
      {
        number: 7,
        title: "Content-to-Lead",
        summary: "Content-to-Lead mengubah perhatian di platform menjadi hubungan yang dapat ditindaklanjuti melalui konten edukatif, CTA spesifik, dan pertukaran nilai.",
        blocks: [
          { type: "subhead", text: "Konten adalah pintu, bukan tujuan akhir" },
          { type: "paragraph", text: "Content-to-Lead adalah alur dari seseorang menemukan konten sampai ia memilih masuk ke database. Konten edukasi berfungsi sebagai pintu masuk karena membantu audience mengenali masalah, memahami pilihan, atau memperoleh quick win. Namun view, like, dan follower masih merupakan perhatian yang dipinjam dari platform. CTA mengajak orang memindahkan hubungan ke langkah yang lebih jelas: mengunduh, mendaftar, meminta hasil, atau memulai percakapan." },
          { type: "paragraph", text: "Instagram dan TikTok efektif untuk demonstrasi singkat, visual, serta penemuan topik. Threads dapat menguji sudut pandang dan percakapan ringkas. YouTube cocok untuk penjelasan mendalam dan konten yang dicari kembali. Facebook dapat menjangkau komunitas atau kelompok minat tertentu. LinkedIn relevan untuk konteks profesional dan B2B. Ini bukan aturan mutlak; pilih kanal berdasarkan kebiasaan audience dan format yang mampu Anda produksi konsisten." },
          { type: "subhead", text: "CTA yang menghasilkan leads" },
          { type: "paragraph", text: "CTA atau call to action adalah instruksi tentang langkah berikutnya dan alasan mengambilnya. ‘Hubungi kami’ terlalu umum. ‘Isi checklist 2 menit untuk melihat tiga area pemborosan operasional’ lebih jelas karena menyebut aktivitas, waktu, dan output. CTA dapat mengarah ke landing page, form, chat dengan kata kunci, webinar, atau tools. Pastikan destination melanjutkan janji yang dibuat konten." },
          { type: "paragraph", text: "Dari follower menjadi database tidak berarti memindahkan semua follower. Saring secara alami dengan topik dan offer. Konsultan HR, misalnya, membuat carousel tentang tanda proses onboarding tidak konsisten. CTA menawarkan worksheet audit onboarding. Orang yang mengisinya memilih ukuran tim dan tantangan utama. Follow-up kemudian membahas masalah onboarding, bukan langsung menjual seluruh layanan HR." },
          { type: "paragraph", text: "Gunakan rangkaian konten dengan fungsi berbeda. Konten awareness menamai masalah. Konten education menjelaskan penyebab dan opsi. Konten proof menunjukkan proses atau pengalaman customer tanpa klaim berlebihan. Konten invitation menawarkan lead magnet. Satu konten tidak harus melakukan semuanya. Yang penting, jalur dari topik ke CTA terasa logis." },
          { type: "subhead", text: "Kesalahan yang perlu dihindari" },
          { type: "list", items: ["Menyisipkan CTA yang tidak berhubungan dengan isi konten.", "Mengukur semua konten hanya dari reach.", "Menggunakan format sama persis di setiap platform tanpa menyesuaikan cara konsumsi.", "Membuat CTA terlalu banyak dalam satu konten.", "Tidak mencatat platform dan konten sumber lead."] },
          { type: "subhead", text: "Aksi bab ini" },
          { type: "list", items: ["Pilih satu platform utama dan satu masalah audience.", "Buat tiga konten: awareness, education, dan invitation.", "Tulis satu CTA dengan tindakan, durasi, serta hasil yang jelas.", "Tambahkan penanda sumber agar lead dapat diukur sampai conversion."] },
          { type: "subhead", text: "Peta konsep bab" },
          { type: "list", items: ["Instagram", "TikTok", "Threads", "YouTube", "Facebook", "LinkedIn", "Konten edukasi sebagai pintu masuk", "CTA yang menghasilkan leads", "Dari follower menjadi database"] }
        ]
      }
    ]
  }
];

window.EBOOK_PARTS_1_3_EXPANDED.find((part) => part.id === "bagian-2").chapters.push(
  {
    number: 13,
    title: "Customer-to-Lead",
    summary: "Customer lama adalah sumber peluang yang kaya konteks: hubungan dapat berkembang melalui repeat purchase, cross-sell, upsell, referral, atau reactivation yang relevan.",
    blocks: [
      { type: "subhead", text: "Jangan mulai lagi dari nol" },
      { type: "paragraph", text: "Customer lama sudah melewati hambatan yang belum dilewati lead baru: mengenal brand, menilai offer, dan mencoba pengalaman transaksi. Karena itu mereka sering menjadi sumber leads termurah dalam arti biaya membangun kepercayaan awal sudah dikeluarkan. Namun ‘lebih murah’ bukan alasan menghubungi tanpa batas. Gunakan riwayat pembelian, kebutuhan lanjutan, kepuasan, dan timing agar komunikasi tetap berguna." },
      { type: "paragraph", text: "Repeat purchase adalah pembelian produk atau layanan yang sama kembali, seperti isi ulang, servis berkala, atau perpanjangan. Cross-sell menawarkan produk pelengkap yang menyelesaikan pekerjaan terkait. Upsell menawarkan versi, kapasitas, atau paket yang lebih tinggi ketika manfaat tambahannya memang sesuai. Bedanya bukan sekadar harga: cross-sell memperluas solusi; upsell memperbesar atau meningkatkan solusi yang dipilih." },
      { type: "paragraph", text: "Referral terjadi ketika customer memperkenalkan orang lain. Lead hasil referral sebaiknya tetap masuk melalui invitation atau form yang menjelaskan konteks—bukan meminta customer menyerahkan nomor temannya untuk dihubungi tiba-tiba. Berikan cara mudah untuk membagikan link, kode, atau resource. Insentif boleh ada, tetapi pengalaman yang layak direkomendasikan tetap fondasinya." },
      { type: "subhead", text: "Reactivation dan siklus kebutuhan" },
      { type: "paragraph", text: "Reactivation mengajak customer yang sudah lama tidak aktif untuk kembali berinteraksi. Mulailah dengan alasan relevan: saatnya servis, ada cara penggunaan baru, kategori yang dulu dicari tersedia, atau minta update kebutuhan. Jangan berpura-pura personal bila tidak memiliki konteks. Anda juga dapat bertanya apakah topik tersebut masih penting sebelum mengirim offer." },
      { type: "paragraph", text: "Contoh: roastery mencatat jenis kopi, metode seduh, dan interval rata-rata pembelian. Menjelang perkiraan stok habis, customer mendapat reminder reorder. Pembeli biji espresso dapat menerima cross-sell cairan pembersih mesin; pelanggan volume tinggi dapat ditawarkan upsell langganan yang memberi jadwal tetap. Setelah pengalaman baik, mereka menerima link referral untuk teman—teman tersebut memilih sendiri apakah ingin klaim sample." },
      { type: "subhead", text: "Kesalahan yang perlu dihindari" },
      { type: "list", items: ["Menganggap transaksi lama sebagai izin untuk semua promosi.", "Menawarkan upsell sebelum customer memperoleh hasil dari pembelian awal.", "Mengirim cross-sell yang tidak berhubungan dengan penggunaan.", "Meminta nomor teman tanpa mekanisme opt-in.", "Mengaktifkan kembali customer hanya dengan diskon berulang."] },
      { type: "subhead", text: "Aksi bab ini" },
      { type: "list", items: ["Petakan siklus repeat purchase untuk satu produk.", "Pilih satu cross-sell dan satu upsell yang memiliki alasan penggunaan jelas.", "Buat referral link yang dapat dibagikan tanpa menyerahkan kontak orang lain.", "Tulis pesan reactivation yang menanyakan kebutuhan sebelum menawarkan."] },
      { type: "subhead", text: "Peta konsep bab" },
      { type: "list", items: ["Customer lama", "Repeat purchase", "Referral", "Cross-sell", "Upsell", "Reactivation", "Kenapa customer lama sering menjadi sumber leads termurah"] }
    ]
  },
  {
    number: 14,
    title: "Interactive Lead Magnet dan AI",
    summary: "Interactive lead magnet mengolah input pengguna menjadi hasil yang relevan; AI dapat membantu proses, tetapi manfaat, batasan, dan keputusan akhir harus tetap jelas.",
    blocks: [
      { type: "subhead", text: "Dari file statis menuju personalized experience" },
      { type: "paragraph", text: "Interactive lead magnet meminta pengguna melakukan sesuatu—memilih, menjawab, atau memasukkan data—lalu memberikan output yang menyesuaikan input. Karena pengguna ikut berpartisipasi, hasil terasa lebih dekat dengan situasinya dibanding ebook umum. Bisnis juga memperoleh context data yang dapat dipakai untuk segmentasi. Pertukarannya harus adil: jangan meminta informasi sensitif yang tidak diperlukan hanya demi personalisasi." },
      { type: "paragraph", text: "Quiz biasanya terdiri dari pertanyaan ringan dengan kategori hasil, misalnya ‘gaya konten mana yang cocok untuk bisnismu?’ Assessment menilai kondisi terhadap dimensi atau kriteria, misalnya kesiapan sistem follow-up berdasarkan sumber lead, pencatatan, response process, dan nurturing. Yang di-assess harus disebutkan dengan jelas; outputnya bisa berupa level, gap, prioritas, dan langkah awal—bukan diagnosis atau kepastian profesional." },
      { type: "paragraph", text: "Calculator menghitung angka dari formula yang transparan. Kalkulator katering dapat menerima jumlah orang, hari, dan budget per porsi untuk menghasilkan estimasi kebutuhan bulanan. Generator menyusun draft dari pilihan pengguna, seperti ide headline berdasarkan kategori dan manfaat. AI tools dapat merangkum jawaban terbuka, menyusun opsi, atau memberi pola awal. AI bukan label ajaib; jelaskan input apa yang diproses, output apa yang dihasilkan, dan bahwa pengguna perlu meninjau hasil." },
      { type: "subhead", text: "Personalized report yang berguna" },
      { type: "paragraph", text: "Personalized report menggabungkan jawaban menjadi penjelasan terstruktur: kondisi sekarang, alasan hasil, prioritas, rekomendasi awal, dan next action. Report yang baik tidak hanya menampilkan skor. Ia mengajarkan hubungan antara jawaban dan rekomendasi, serta membedakan hal yang bisa dilakukan sendiri dari hal yang membutuhkan bantuan." },
      { type: "paragraph", text: "Misalnya agency iklan membuat assessment kelayakan paid ads untuk UMKM. Input: margin kasar, kapasitas melayani order, kejelasan offer, aset creative, dan kemampuan follow-up. Proses memberi skor pada kesiapan operasional, bukan menjanjikan performa iklan. Output menyebut dua gap utama dan checklist perbaikan. Lead dengan pondasi kuat dapat ditawarkan audit; lead yang belum siap menerima materi persiapan. Contoh ini hipotetis." },
      { type: "paragraph", text: "Interactive lead magnet semakin menarik karena memberi hasil segera, memperjelas masalah, dan menciptakan micro-commitment. Namun interaksi bukan tujuan. Jika pertanyaan panjang, hasil generik, atau report hanya jembatan menuju pitch, pengguna akan merasa waktunya diambil. Dari ‘download ebook’ menuju personalized experience berarti menambah relevansi, bukan menambah kerumitan." },
      { type: "subhead", text: "Kesalahan yang perlu dihindari" },
      { type: "list", items: ["Membuat quiz hiburan yang tidak berkaitan dengan solusi.", "Tidak menjelaskan apa yang di-assess atau dihitung.", "Menyembunyikan formula dasar di balik skor misterius.", "Memperlakukan output AI sebagai fakta yang pasti benar.", "Meminta data berlebihan sebelum menunjukkan nilai."] },
      { type: "subhead", text: "Aksi bab ini" },
      { type: "list", items: ["Tentukan satu keputusan kecil yang ingin dibantu.", "Tulis input, aturan proses, output, dan keterbatasan.", "Buat tiga kategori hasil yang benar-benar memerlukan next action berbeda.", "Uji apakah report tetap berguna jika pengguna tidak membeli."] },
      { type: "subhead", text: "Peta konsep bab" },
      { type: "list", items: ["Quiz", "Assessment", "Calculator", "AI tools", "Generator", "Personalized report", "Mengapa interactive lead magnet semakin menarik", "Dari ‘download ebook’ menuju personalized experience"] }
    ]
  },
  {
    number: 15,
    title: "Mendesain Lead Funnel",
    summary: "Lead funnel adalah rangkaian langkah dari sumber perhatian sampai data berizin tersimpan; desain yang baik menjaga kesinambungan janji dan next action.",
    blocks: [
      { type: "subhead", text: "Lihat funnel dari mata pengguna" },
      { type: "flow", items: ["Traffic", "Offer", "Landing Page / Chat / Form", "Opt-in", "Lead Database"] },
      { type: "paragraph", text: "Traffic source adalah tempat orang menemukan ajakan: konten, search, ads, event, partner, toko, atau referral. Lead magnet adalah nilai yang ditukar dengan perhatian dan data. Landing page menjelaskan untuk siapa offer dibuat, masalah yang dibantu, apa yang diterima, dan apa yang terjadi sesudahnya. Chat cocok untuk percakapan; form cocok untuk capture terstruktur. Pilih jalur berdasarkan kompleksitas keputusan dan kapasitas tim." },
      { type: "paragraph", text: "Form meminta data minimum yang berguna untuk deliver dan segmentasi. Nama, kanal kontak, serta satu pertanyaan masalah sering lebih bermanfaat daripada sepuluh field demografis. WhatsApp opt-in harus menyebut bahwa tindak lanjut dilakukan melalui WhatsApp serta konteksnya. Opt-in bukan detail administratif di akhir; ia bagian dari promise." },
      { type: "paragraph", text: "Thank-you page mengonfirmasi tindakan berhasil, mengirim atau membuka lead magnet, dan menjelaskan next action. Halaman ini dapat meminta micro-commitment yang wajar: memilih topik, menyimpan nomor, menonton tutorial, atau menjadwalkan sesi. Jangan langsung membanjiri dengan banyak tombol dan upsell yang mengalihkan dari janji utama." },
      { type: "subhead", text: "Satu janji dari awal sampai akhir" },
      { type: "paragraph", text: "Funnel yang konsisten mempertahankan message match. Jika iklan menawarkan checklist memilih vendor renovasi, landing page, form, thank-you page, dan WhatsApp pertama harus tetap membahas checklist tersebut. Pergantian mendadak ke promo rumah membuat pengguna meragukan hubungan. Simpan parameter atau tag sumber agar database mengetahui jalur yang diambil." },
      { type: "paragraph", text: "Contoh: layanan laundry hotel membuat iklan ‘Hitung kebutuhan linen cadangan’. Landing page menjelaskan calculator dan input jumlah kamar, pergantian harian, serta siklus laundry. Form meminta email atau WhatsApp untuk menyimpan hasil. Thank-you page menampilkan ringkasan dan menawarkan checklist audit linen. Database mencatat segmen hotel serta estimasi volume; next action untuk volume besar adalah konsultasi, sedangkan pengguna yang masih riset menerima edukasi." },
      { type: "subhead", text: "Kesalahan yang perlu dihindari" },
      { type: "list", items: ["Mengirim traffic ke halaman yang janji dan CTA-nya berbeda.", "Meminta data tanpa menjelaskan pemakaiannya.", "Membuat form panjang untuk offer sederhana.", "Tidak menguji delivery lead magnet.", "Membiarkan thank-you page menjadi jalan buntu."] },
      { type: "subhead", text: "Aksi bab ini" },
      { type: "list", items: ["Gambar funnel pada satu halaman.", "Tuliskan promise persis di setiap tahap.", "Hapus field yang tidak mengubah delivery, segmentasi, atau follow-up.", "Jalankan funnel sendiri dari sumber traffic hingga pesan pertama."] },
      { type: "subhead", text: "Peta konsep bab" },
      { type: "list", items: ["Traffic source", "Lead magnet", "Landing page", "Form", "WhatsApp opt-in", "Thank-you page", "Next action"] }
    ]
  },
  {
    number: 16,
    title: "Jangan Mengejar Banyak Leads, Kejar Leads yang Benar",
    summary: "Lead yang benar memiliki kombinasi intent, awareness, fit, kemampuan, dan timing yang memungkinkan bisnis membantu serta menindaklanjuti secara masuk akal.",
    blocks: [
      { type: "subhead", text: "Kualitas bukan satu label" },
      { type: "paragraph", text: "Lead quality adalah tingkat kemungkinan sebuah lead cocok, maju, dan menciptakan nilai yang sehat bagi kedua pihak. Intent menunjukkan kekuatan tindakan: membaca artikel berbeda dari meminta demo. Problem awareness menunjukkan sejauh mana seseorang mengenali masalah. Product fit menilai apakah solusi Anda memang sesuai dengan kebutuhan, skala, cara kerja, atau batasannya." },
      { type: "paragraph", text: "Budget adalah kemampuan atau alokasi untuk menyelesaikan masalah; jangan selalu menanyakannya secara kasar di awal. Kisaran paket, skala kebutuhan, atau cara pembelian dapat menjadi proxy. Urgency menggambarkan kapan masalah perlu ditangani. Lead dengan masalah besar tetapi rencana tahun depan memerlukan nurturing, bukan tekanan. Lead source memberi konteks awal karena referral, search komersial, webinar, dan giveaway sering membawa intent berbeda." },
      { type: "subhead", text: "Lead scoring sebagai alat prioritas" },
      { type: "paragraph", text: "Lead scoring memberi poin berdasarkan fit dan behavior untuk membantu tim menentukan prioritas. Misalnya, jasa training menambah skor untuk ukuran tim yang sesuai, kebutuhan dalam 60 hari, kunjungan halaman program, serta permintaan proposal. Skor dikurangi bila lokasi tidak terlayani atau kebutuhan di luar keahlian. Bobot ini adalah hipotesis operasional yang harus diperiksa terhadap conversion nyata, bukan kebenaran universal." },
      { type: "paragraph", text: "Qualified vs unqualified leads bukan berarti orang baik dan buruk. Qualified berarti sesuai kriteria untuk langkah tertentu sekarang. Unqualified dapat berarti belum waktunya, bukan pengambil keputusan, kebutuhan tidak cocok, atau data belum cukup. Responsnya bisa nurturing, referral ke solusi lain, permintaan informasi tambahan, atau berhenti secara sopan. Qualification melindungi waktu sales sekaligus mencegah customer membeli solusi yang tidak tepat." },
      { type: "subhead", text: "Contoh praktis" },
      { type: "paragraph", text: "Studio produksi video menerima 100 lead dari template storyboard dan 15 lead dari form brief perusahaan. Kelompok pertama mungkin berisi kreator yang ingin belajar; kelompok kedua mencantumkan tujuan, jumlah video, deadline, dan rentang produksi. Studio tidak serta-merta membuang lead template. Mereka mengirim edukasi self-service, sementara brief yang fit diprioritaskan untuk discovery call. Dua jalur tersebut menilai tujuan berbeda." },
      { type: "subhead", text: "Kesalahan yang perlu dihindari" },
      { type: "list", items: ["Menyamakan lead murah dengan lead berkualitas.", "Membuat skor dari data yang tidak berkaitan dengan conversion.", "Menganggap urgency tinggi selalu berarti product fit tinggi.", "Mendorong unqualified lead ke sales hanya demi target aktivitas.", "Tidak memperbarui kriteria dari hasil customer nyata."] },
      { type: "subhead", text: "Aksi bab ini" },
      { type: "list", items: ["Definisikan fit, intent, dan timing untuk satu offer.", "Pilih lima sinyal yang dapat diamati.", "Buat tiga jalur: sales sekarang, nurturing, dan tidak cocok.", "Bandingkan sumber lead menggunakan qualified lead rate, bukan volume saja."] },
      { type: "subhead", text: "Peta konsep bab" },
      { type: "list", items: ["Lead quality", "Intent", "Problem awareness", "Product fit", "Budget", "Urgency", "Lead source", "Lead scoring", "Qualified vs unqualified leads"] }
    ]
  }
);

window.EBOOK_PARTS_1_3_EXPANDED.push({
  id: "bagian-3", number: "03", title: "Setelah Leads Masuk, Jangan Langsung Jualan", accent: "Attention → trust",
  chapters: [
    {
      number: 17,
      title: "The Follow-Up Gap",
      summary: "Banyak potensi hilang bukan karena leads kurang, melainkan karena tidak ada sistem yang memastikan setiap lead menerima respons dan langkah berikutnya.",
      blocks: [
        { type: "subhead", text: "Kebocoran setelah capture" },
        { type: "paragraph", text: "Banyak bisnis sebenarnya tidak kekurangan leads. Mereka kekurangan follow-up. Form masuk ke inbox yang jarang dibuka, chat tidak diberi label, peserta acara tidak pernah menerima materi, atau sales menyimpan catatan di perangkat pribadi. Lead generation terlihat sibuk, tetapi hubungan berhenti tepat setelah orang menunjukkan minat. Inilah follow-up gap: jarak antara sinyal lead dan respons bisnis yang relevan." },
        { type: "paragraph", text: "Leads masuk tetapi tidak pernah disentuh lagi biasanya karena ownership kabur. Marketing merasa tugas selesai setelah capture; sales menunggu lead yang ‘siap’; sistem tidak mencatat status. Leads bertanya lalu hilang ketika jawaban lambat, generik, atau tidak diikuti next action. Sales lupa follow-up saat volume chat tinggi karena mengandalkan ingatan, bukan queue, reminder, dan data aktivitas." },
        { type: "subhead", text: "Potensi revenue yang bocor" },
        { type: "paragraph", text: "Revenue leak tidak selalu terlihat sebagai penolakan. Ia tampak sebagai form tanpa balasan, quotation tanpa tanggal follow-up, demo tanpa rangkuman, atau lead lama yang tidak pernah ditinjau. Tidak semua kebocoran bisa berubah menjadi penjualan, dan kita tidak boleh menganggap setiap lead pasti membeli. Namun setiap lead yang cocok seharusnya mendapat proses yang konsisten agar keputusan tidak gagal hanya karena bisnis lupa." },
        { type: "paragraph", text: "Follow-up yang baik memiliki owner, waktu respons, status, next action, dan aturan eskalasi. Automation dapat mengirim konfirmasi dan memenuhi janji awal. Manusia mengambil alih untuk pertanyaan, kebutuhan kompleks, atau sinyal niat. Jika lead belum siap, ia masuk nurturing. Jika tidak cocok, status ditutup dengan alasan. Sistem mengurangi ketergantungan pada memori tanpa menghilangkan percakapan manusia." },
        { type: "subhead", text: "Contoh praktis" },
        { type: "paragraph", text: "Wedding organizer menerima enquiry dari Instagram, website, dan pameran. Sebelumnya semua masuk ke chat berbeda. Setelah dipetakan, setiap enquiry dicatat dengan tanggal acara, kota, jumlah tamu, dan sumber. Konfirmasi otomatis menyebut kapan tim membalas. Koordinator mendapat task; setelah konsultasi, status berubah menjadi proposal dikirim beserta tanggal follow-up. Lead yang tanggalnya belum pasti menerima panduan perencanaan. Tidak ada janji bahwa semua akan closing, tetapi tidak ada lagi lead yang hilang tanpa keputusan." },
        { type: "subhead", text: "Kesalahan yang perlu dihindari" },
        { type: "list", items: ["Mengatasi gap hanya dengan menyuruh sales lebih rajin.", "Mengirim reminder otomatis tanpa melihat status terbaru.", "Tidak menghentikan sequence ketika lead sudah merespons.", "Membiarkan lead tanpa owner.", "Menyamakan respons cepat dengan jawaban tergesa-gesa yang tidak membantu."] },
        { type: "subhead", text: "Aksi bab ini" },
        { type: "list", items: ["Audit 30 lead terakhir: sumber, respons pertama, owner, status, dan next action.", "Hitung berapa yang tidak pernah mendapat respons atau follow-up.", "Buat daftar status sederhana dan definisinya.", "Tetapkan satu queue harian untuk lead yang membutuhkan tindakan manusia."] },
        { type: "subhead", text: "Peta konsep bab" },
        { type: "list", items: ["Banyak bisnis sebenarnya tidak kekurangan leads", "Mereka kekurangan follow-up", "Leads masuk tetapi tidak pernah disentuh lagi", "Leads bertanya lalu hilang", "Sales lupa follow-up", "Potensi revenue yang bocor"] }
      ]
    },
    {
      number: 18,
      title: "Tidak Semua Leads Siap Membeli Hari Ini",
      summary: "Kesiapan membeli berubah berdasarkan awareness, fit, kebutuhan, dan timing; follow-up harus membantu lead bergerak, bukan memperlakukan semua orang sebagai hot lead.",
      blocks: [
        { type: "subhead", text: "Temperatur lead adalah snapshot" },
        { type: "paragraph", text: "Cold Lead memiliki minat awal atau kecocokan, tetapi engagement dan kesiapan masih rendah. Warm Lead sudah menunjukkan keterlibatan lebih dalam—misalnya mengikuti webinar, membandingkan opsi, atau menjawab assessment. Hot Lead menunjukkan sinyal tindakan dekat seperti meminta proposal, ketersediaan, demo, atau cara membayar. Label ini adalah snapshot, bukan identitas permanen. Lead dapat menghangat, mendingin, atau berhenti cocok." },
        { type: "paragraph", text: "Timing pembelian sering berada di luar kontrol bisnis: kontrak lama belum selesai, anggaran baru tersedia kuartal depan, pindah rumah belum pasti, atau tim perlu persetujuan. Menekan lead tidak mengubah kendala tersebut. Sistem yang baik mencatat timing, memberi materi sesuai tahap, dan kembali saat ada alasan. Pertanyaan seperti ‘kapan Anda perlu hasil ini?’ lebih berguna daripada menebak dari jumlah chat." },
        { type: "subhead", text: "Empat tingkat awareness" },
        { type: "paragraph", text: "Problem aware berarti orang mengenali gejala atau masalah, tetapi belum tahu jalan keluar. Solution aware berarti ia memahami kategori solusi, misalnya menggunakan software, konsultan, atau proses manual. Product aware berarti ia mengenal produk atau penyedia tertentu dan sedang menilai kecocokan. Ready to buy berarti informasi utama cukup, risiko dapat diterima, dan ada kemampuan serta momentum untuk bertindak." },
        { type: "paragraph", text: "Pesan harus menjawab pertanyaan tahap tersebut. Problem-aware lead membutuhkan diagnosis dan konsekuensi. Solution-aware lead membutuhkan perbandingan pendekatan. Product-aware lead membutuhkan proses, proof, batasan, harga, atau implementasi. Ready-to-buy lead membutuhkan CTA yang jelas dan respons manusia yang sigap. Memberi diskon kepada orang yang masih belum memahami masalah hanya mempercepat kebingungan." },
        { type: "subhead", text: "Contoh praktis" },
        { type: "paragraph", text: "Pemilik kos membaca artikel tentang kebocoran biaya listrik dan mengunduh checklist—cold/problem aware. Setelah mengisi calculator serta melihat opsi monitoring, ia menjadi warm/solution aware. Ia kemudian menanyakan pemasangan untuk 30 kamar dan meminta proposal—hot/product aware. Namun renovasi baru dilakukan dua bulan lagi. Walau intent tinggi, timing belum hari ini. Penyedia mencatat bulan keputusan, mengirim checklist persiapan instalasi, dan menjadwalkan follow-up yang relevan." },
        { type: "subhead", text: "Kesalahan yang perlu dihindari" },
        { type: "list", items: ["Menilai hot hanya karena lead membuka pesan.", "Mengirim penjelasan dasar panjang kepada lead yang meminta invoice.", "Menganggap ‘belum sekarang’ sama dengan penolakan permanen.", "Tidak mencatat alasan dan timing penundaan.", "Membuat nurture tanpa jalan bagi lead yang siap lebih cepat."] },
        { type: "subhead", text: "Aksi bab ini" },
        { type: "list", items: ["Definisikan sinyal cold, warm, dan hot untuk bisnis Anda.", "Petakan satu pertanyaan utama di tiap tingkat awareness.", "Tambahkan field timing dan alasan penundaan.", "Sediakan jalur cepat bagi lead yang menyatakan siap bertindak."] },
        { type: "subhead", text: "Peta konsep bab" },
        { type: "list", items: ["Cold Lead", "Warm Lead", "Hot Lead", "Timing pembelian", "Problem aware", "Solution aware", "Product aware", "Ready to buy"] }
      ]
    },
    {
      number: 19,
      title: "Dari Attention Menuju Trust",
      summary: "Attention membuka pintu, tetapi trust tumbuh melalui edukasi, bukti, konsistensi, dan pengalaman kecil sebelum lead bersedia mengambil tindakan.",
      blocks: [
        { type: "subhead", text: "Perjalanan psikologis, bukan trik" },
        { type: "flow", items: ["Know", "Like", "Trust", "Desire", "Action"] },
        { type: "paragraph", text: "Know berarti orang mengenali siapa Anda dan masalah yang dibahas. Like bukan harus menyukai secara pribadi; mereka merasa cara komunikasi, perspektif, atau nilai Anda cocok. Trust berarti mereka menilai bisnis cukup kompeten dan dapat dipercaya untuk langkah berikutnya. Desire muncul ketika manfaat solusi terasa relevan. Action adalah tindakan nyata: reply, booking, trial, atau transaksi. Alur dapat maju-mundur dan tidak selalu seragam." },
        { type: "paragraph", text: "Awareness memperoleh perhatian dengan menamai situasi yang dialami audience. Education membantu memahami penyebab, pilihan, serta trade-off. Authority adalah alasan yang dapat diverifikasi untuk mempercayai keahlian: proses yang jelas, demonstrasi, pengalaman relevan, atau pengetahuan yang konsisten—bukan gelar dan jargon semata. Social proof menunjukkan pengalaman orang lain, tetapi harus spesifik, jujur, dan tidak dijadikan jaminan hasil." },
        { type: "subhead", text: "Trust sebagai akumulasi bukti kecil" },
        { type: "paragraph", text: "Trust tumbuh dari banyak detail: lead magnet datang tepat, instruksi mudah diikuti, batasan dijelaskan, pertanyaan dijawab, dan CTA sesuai tahap. Offer kemudian menyatukan masalah, solusi, manfaat, bukti, risiko, harga, serta langkah membeli. Jika offer datang sebelum pemahaman dan rasa aman, lead harus menanggung terlalu banyak ketidakpastian sekaligus." },
        { type: "paragraph", text: "Contoh: produsen frozen food B2B ingin memasok kafe. Konten awareness membahas variasi waktu persiapan dapur. Education menunjukkan cara menghitung food cost dan konsistensi porsi. Authority muncul lewat video proses quality control dan spesifikasi penyimpanan. Social proof berupa cerita penggunaan yang diberi konteks, tanpa klaim hasil pasti. Lead kemudian mendapat sample kit dan panduan uji menu. Offer kontrak pasokan datang setelah kafe memahami kualitas, proses, dan fit." },
        { type: "paragraph", text: "Trust juga membutuhkan kejujuran tentang siapa yang tidak cocok. Menjelaskan minimum order, area layanan, atau kapasitas sejak awal dapat mengurangi volume lead, tetapi meningkatkan kejelasan. Desire yang sehat lahir dari kecocokan, bukan fear buatan. Action dibuat mudah dengan satu CTA yang jelas dan respons yang konsisten." },
        { type: "subhead", text: "Kesalahan yang perlu dihindari" },
        { type: "list", items: ["Mengejar attention dengan janji yang tidak dapat dipenuhi.", "Menyamakan authority dengan menyebut diri terbaik.", "Menggunakan testimonial tanpa konteks atau sebagai jaminan.", "Mengulang edukasi tanpa pernah menawarkan next action.", "Menciptakan desire lewat tekanan yang tidak nyata."] },
        { type: "subhead", text: "Aksi bab ini" },
        { type: "list", items: ["Audit satu journey dari konten pertama sampai offer.", "Temukan satu pertanyaan trust yang belum dijawab.", "Tambahkan proof yang relevan dan bisa diperiksa.", "Buat satu CTA yang sesuai tahap, bukan selalu membeli."] },
        { type: "subhead", text: "Peta konsep bab" },
        { type: "list", items: ["Awareness", "Education", "Authority", "Social proof", "Trust", "Offer"] }
      ]
    },
    {
      number: 20,
      title: "Nurturing Bukan Mengirim Promo Setiap Hari",
      summary: "Nurturing adalah rangkaian interaksi yang membantu lead memahami masalah, menilai solusi, dan siap mengambil keputusan; promo hanyalah salah satu elemennya.",
      blocks: [
        { type: "subhead", text: "Bedakan follow-up dan nurturing" },
        { type: "paragraph", text: "Follow-up adalah tindak lanjut terhadap tindakan atau percakapan tertentu: mengirim materi, menjawab enquiry, mengecek proposal, atau mengonfirmasi jadwal. Nurturing adalah proses lebih panjang untuk membangun pengetahuan, trust, serta kesiapan. Follow-up dapat menjadi bagian dari nurturing, tetapi tidak semua follow-up membutuhkan sequence panjang. Keduanya harus memiliki konteks dan tujuan." },
        { type: "paragraph", text: "Education menjelaskan masalah, cara menilai pilihan, dan quick win. Reminder membantu lead mengingat tindakan yang memang ingin dilakukan—misalnya menghadiri webinar atau melengkapi brief. Engagement mengundang partisipasi melalui pertanyaan, pilihan, reply, atau latihan. Storytelling membuat ide abstrak mudah diikuti melalui situasi, keputusan, konflik, dan pembelajaran; cerita tidak harus dramatis atau direkayasa." },
        { type: "paragraph", text: "Social proof membantu menjawab ‘apakah ini pernah bekerja untuk situasi seperti saya?’ Gunakan konteks: siapa pengguna, masalah, proses, dan hasil yang wajar, dengan izin yang sesuai. Offer menjelaskan pertukaran nilai dan langkah membeli. Soft selling menghubungkan edukasi dengan solusi tanpa tekanan tinggi. Hard selling lebih langsung mengenai produk, harga, deadline yang nyata, dan CTA. Keduanya memiliki tempat; masalah muncul ketika semua pesan adalah hard selling tanpa fondasi." },
        { type: "subhead", text: "Merancang campuran pesan" },
        { type: "paragraph", text: "Tentukan perubahan yang perlu dialami lead. Jika jasa keamanan siber menjual audit untuk UKM, sequence dapat dimulai dengan checklist risiko, lalu menjelaskan prioritas, memberi contoh kebocoran proses yang umum, menunjukkan cara audit dilakukan, menjawab kekhawatiran mengenai gangguan operasional, dan baru menawarkan sesi scope. Setiap pesan menambah satu lapis kejelasan." },
        { type: "paragraph", text: "Frekuensi mengikuti ekspektasi, urgensi, dan nilai baru. Promo setiap hari terasa berulang karena hanya alasan bisnis yang berubah. Nurturing konsisten dapat lebih sering ketika lead mengikuti challenge intensif, atau lebih jarang dalam keputusan jangka panjang. Beri ruang untuk reply, hentikan automation saat manusia mengambil alih, dan gunakan respons sebagai input journey." },
        { type: "subhead", text: "Kesalahan yang perlu dihindari" },
        { type: "list", items: ["Mengganti judul promo tanpa menambah nilai baru.", "Mengirim reminder untuk tindakan yang tidak pernah diminta.", "Membuat storytelling panjang tanpa hubungan dengan masalah lead.", "Menyembunyikan penawaran sehingga lead tidak tahu cara melanjutkan.", "Mengirim sequence yang sama setelah lead membeli atau menolak."] },
        { type: "subhead", text: "Aksi bab ini" },
        { type: "list", items: ["Ambil lima pesan terakhir dan beri label education, reminder, engagement, proof, atau offer.", "Tambahkan satu pesan yang menutup gap pemahaman.", "Tulis satu soft-sell dan satu hard-sell yang jujur untuk offer sama.", "Tetapkan trigger berhenti ketika lead reply atau berubah status."] },
        { type: "subhead", text: "Peta konsep bab" },
        { type: "list", items: ["Follow-up", "Nurturing", "Education", "Reminder", "Engagement", "Storytelling", "Social proof", "Offer", "Soft selling", "Hard selling"] }
      ]
    },
    {
      number: 21,
      title: "The Follow-Up Window",
      summary: "Follow-up window adalah ritme tindak lanjut sejak menit pertama hingga bulan berikutnya; setiap waktu memiliki tujuan dan pesan yang berbeda.",
      blocks: [
        { type: "subhead", text: "Waktu mengubah arti pesan" },
        { type: "paragraph", text: "Lima menit pertama penting untuk mengonfirmasi bahwa tindakan berhasil, bukan untuk memaksa sales selalu menyelesaikan percakapan saat itu juga. Kirim lead magnet, nomor registrasi, atau ekspektasi waktu balasan. Bila lead mengajukan enquiry berniat tinggi dan tim tersedia, respons manusia cepat membantu mempertahankan momentum. Jika di luar jam layanan, sampaikan kapan mereka akan ditangani." },
        { type: "paragraph", text: "Hari pertama berfokus pada fulfillment dan orientasi: apa yang diterima, cara memakai, serta next action. Hari ke-2 dapat memberi quick win atau menanyakan hasil awal. Hari ke-3 memperdalam masalah atau menjawab pertanyaan umum. Hari ke-7 cocok untuk ringkasan, proof, atau ajakan langkah lebih besar setelah lead memiliki waktu mencerna." },
        { type: "paragraph", text: "Hari ke-14 dapat menangani keberatan, membagikan cerita relevan, atau menanyakan timing. Hari ke-30 menutup siklus awal dengan pilihan yang jelas: lanjut percakapan, tetap menerima edukasi, atau berhenti. Bulan berikutnya adalah long-term nurturing berdasarkan minat dan siklus kebutuhan, bukan mengulang sequence yang sama. Angka hari ini adalah kerangka, bukan hukum; keputusan mendesak dan produk berulang memiliki ritme berbeda." },
        { type: "timeline", items: [["5 menit pertama", "Konfirmasi dan penuhi janji"], ["Hari pertama", "Orientasi dan ekspektasi"], ["Hari ke-2", "Quick win atau feedback"], ["Hari ke-3", "Perdalam problem awareness"], ["Hari ke-7", "Ringkasan, proof, atau invitation"], ["Hari ke-14", "Objection dan timing"], ["Hari ke-30", "Pilihan langkah berikutnya"], ["Bulan berikutnya", "Nurturing berdasarkan minat"]] },
        { type: "subhead", text: "Konsisten sekaligus relevan" },
        { type: "paragraph", text: "Follow-up harus konsisten agar lead tidak jatuh di celah operasional. Namun konsistensi adalah kepastian proses, bukan jumlah pesan tetap kepada semua orang. Relevansi memerlukan branching: lead yang membalas masuk percakapan; yang membeli masuk onboarding; yang belum membaca mungkin membutuhkan format lain; yang menyatakan tidak tertarik dihentikan. Setiap pesan memeriksa status terbaru sebelum dikirim." },
        { type: "paragraph", text: "Contoh: lembaga kursus mengirim hasil placement test segera. Hari pertama menjelaskan level. Hari kedua memberi latihan mini. Hari ketiga menjelaskan gap keterampilan. Hari ketujuh mengundang konsultasi kelas. Lead yang meminta jadwal langsung dialihkan ke admin; lead yang mulai bulan depan ditandai tanggalnya. Setelah hari ke-30, hanya yang memilih tetap menerima tips masuk newsletter bulanan." },
        { type: "subhead", text: "Kesalahan yang perlu dihindari" },
        { type: "list", items: ["Mengirim pesan kedua sebelum deliverable pertama diterima.", "Menggunakan urgency yang sama di semua hari.", "Tidak menyesuaikan ritme dengan jam layanan dan siklus keputusan.", "Membiarkan automation berjalan setelah conversion.", "Menganggap diam sebagai izin untuk meningkatkan frekuensi."] },
        { type: "subhead", text: "Aksi bab ini" },
        { type: "list", items: ["Tulis tujuan untuk setiap window, bukan hanya isi pesan.", "Pastikan lima menit pertama memenuhi promise dan mengatur ekspektasi.", "Tambahkan branch untuk reply, purchase, penundaan, dan opt-out.", "Tinjau hasil per tahap lalu sesuaikan ritme dari data nyata."] },
        { type: "subhead", text: "Peta konsep bab" },
        { type: "list", items: ["5 menit pertama", "Hari pertama", "Hari ke-2", "Hari ke-3", "Hari ke-7", "Hari ke-14", "Hari ke-30", "Bulan berikutnya", "Kenapa follow-up harus konsisten tetapi tetap relevan"] }
      ]
    }
  ]
});

